import{_ as a,C as o,o as t,c as i,a2 as r,b as l,w as s,a as d,E as h,a3 as u}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Blue Mod Installer","description":"Mod installer for Minecraft servers with support for CurseForge & Modrinth, built as a Blueprint extension for Pterodactyl Panel.","frontmatter":{"title":"Blue Mod Installer","description":"Mod installer for Minecraft servers with support for CurseForge & Modrinth, built as a Blueprint extension for Pterodactyl Panel."},"headers":[],"relativePath":"blue-mod-installer/index.md","filePath":"blue-mod-installer/index.md","lastUpdated":null}'),p={name:"blue-mod-installer/index.md"};function c(g,e,m,f,b,v){const n=o("Mermaid");return t(),i("div",null,[e[1]||(e[1]=r('<h1 id="blue-mod-installer" tabindex="-1">Blue Mod Installer <a class="header-anchor" href="#blue-mod-installer" aria-label="Permalink to &quot;Blue Mod Installer&quot;">​</a></h1><p><strong>A mod installer for Minecraft servers with support for CurseForge &amp; Modrinth</strong> — a Blueprint extension for the Pterodactyl panel that lets your users search, browse, and install mods straight into their server&#39;s <code>/mods</code> directory from the server dashboard.</p><p>Blue Mod Installer adds a <strong>Mod Installer</strong> tab to every server&#39;s sidebar. Users pick a provider (Modrinth or CurseForge), filter by loader and Minecraft version, browse versions, and install with one click — the panel resolves the download through the provider&#39;s API and has Wings pull the file directly onto the node.</p><div class="tip custom-block" style="margin-top:1.5rem;"><p><strong>Built for PingLess Studios by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer">AnAverageBeing</a></strong><a href="https://github.com/AnAverageBeing/blue-mod-installer" target="_blank" rel="noreferrer">GitHub Repo</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Studio</a></p></div><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>',6)),(t(),l(u,null,{default:s(()=>[h(n,{id:"mermaid-18",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20Panel%5BPterodactyl%20Panel%5D%0A%20%20%20%20%20%20%20%20UI%5BServer%20Sidebar%20-%20Mod%20Installer%20tab%5D%20--%3E%20API%5BClient%20API%20%2Fapi%2Fclient%2Fextensions%2Fbluemodinstaller%5D%0A%20%20%20%20%20%20%20%20ADMIN%5BAdmin%20Settings%20Page%5D%20--%3E%20STORE%5B(Extension%20Settings)%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20STORE%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Providers%5BMod%20Providers%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%7Csearch%20%2B%20versions%7C%20MR%5BModrinth%20API%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%7Csearch%20%2B%20versions%7C%20CF%5BCurseForge%20API%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Node%5BWings%20Node%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%7Cpull%20URL%7C%20WINGS%5BWings%20Daemon%5D%0A%20%20%20%20%20%20%20%20WINGS%20--%3E%20MODS%5B%22server%20%2Fmods%20directory%22%5D%0A%20%20%20%20end%0A%20%20%20%20MR%20--%3E%7Cdownload%20URL%7C%20API%0A%20%20%20%20CF%20--%3E%7Cdownload%20URL%7C%20API%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r(`<p>The <strong>panel</strong> proxies all provider traffic: searches and version lookups are forwarded to Modrinth/CurseForge with your CurseForge API key applied server-side (users never see it). For installs, the panel resolves the real file URL for the chosen version and instructs <strong>Wings</strong> to pull it into the server&#39;s <code>/mods</code> folder in the foreground.</p><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Two providers, one UI</strong> — Modrinth (keyless) and CurseForge (API key set once by the admin, kept server-side).</li><li><strong>Rich search</strong> — text query, loader filter (Fabric, Forge, NeoForge, …), Minecraft version filter, sort modes, paginated results.</li><li><strong>Version browser</strong> — every version of a mod with game versions, loaders, and download counts before installing.</li><li><strong>One-click install</strong> — the resolved file is pulled by Wings into <code>/mods</code> in the foreground; the user sees success/failure immediately.</li><li><strong>Permission-aware</strong> — browsing requires <code>file.read</code>, installing requires <code>file.create</code> on the server.</li><li><strong>Admin defaults</strong> — default provider, items per page (6/12/24/48), and the CurseForge API key from <strong>Admin → Extensions → Blue Mod Installer</strong>.</li><li><strong>Blueprint-native</strong> — installs with one <code>blueprint -install</code> command; a manual standalone path ships for panels where the CLI can&#39;t run.</li></ul><hr><h2 id="blueprint-vs-standalone" tabindex="-1">Blueprint vs Standalone <a class="header-anchor" href="#blueprint-vs-standalone" aria-label="Permalink to &quot;Blueprint vs Standalone&quot;">​</a></h2><p>Both distributions ship the <strong>same</strong> extension source. The difference is only how it lands on your panel.</p><table tabindex="0"><thead><tr><th></th><th>Blueprint (recommended)</th><th>Standalone (manual)</th></tr></thead><tbody><tr><td>Installer</td><td><code>blueprint -install bluemodinstaller-vX.Y.Z.blueprint</code></td><td>Hand-placed files per <code>standalone/INSTALLATION.md</code></td></tr><tr><td>Requirement</td><td>Blueprint CLI on the panel</td><td>Blueprint <strong>framework</strong> on the panel (no CLI)</td></tr><tr><td>Updates</td><td>Install the newer <code>.blueprint</code></td><td>Repeat the manual steps</td></tr><tr><td>Removal</td><td><code>blueprint -remove bluemodinstaller</code></td><td>Reverse the manual steps</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Standalone still needs the Blueprint framework</p><p>The controllers use <code>BlueprintAdminLibrary</code> and the React components import through Blueprint&#39;s <code>@/blueprint/extensions/*</code> alias. There is no Blueprint-free variant of this addon — the standalone path only replaces the CLI.</p></div><hr><h2 id="quick-install" tabindex="-1">Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bluemodinstaller-v1.12.4.blueprint</span></span></code></pre></div><p>Then open <strong>Admin → Extensions → Blue Mod Installer</strong> and set your CurseForge API key (only needed for CurseForge results).</p><p>See <a href="./getting-started/installation">Installation</a> for the full guide, and the <a href="./configuration/reference">Configuration Reference</a> for every setting.</p>`,14))])}const B=a(p,[["render",c]]);export{k as __pageData,B as default};
